export function interiorCompatibility(s,key,id){
 if(key!=='harness'||id==='stock')return '';
 if(id==='six'&&(s.frontSeats!=='bucket'||s.rollCage!=='full'))return 'Six-point harnesses require BUCKET SEATS and a FULL CAGE.';
 if(id==='four'&&(!['sport','bucket'].includes(s.frontSeats)||!['half','full'].includes(s.rollCage)&&s.chassis!=='reinforced'))return 'Four-point harnesses require SPORT/BUCKET SEATS and a cage or REINFORCED CHASSIS.';
 return '';
}
export function sanitizeInteriorSelection(s){if(interiorCompatibility(s,'harness',s.harness))s.harness='stock';}
export function resolveInteriorTuning(s){
 const cage=s.rollCage==='full'?'full':s.rollCage==='half'?'half':s.chassis==='reinforced'?'legacy':'none';
 const mass=({sport:-.4,dish:-.2}[s.steeringWheel]||0)+({sport:-8,bucket:-18}[s.frontSeats]||0)+({ball:.1,tall:.2}[s.shiftKnob]||0)+({extended:.4,hydraulic:1.8}[s.handbrakeLever]||0)+({half:28,full:42}[s.rollCage]||0)-(s.rollCage!=='stock'&&s.chassis==='reinforced'?12:0)+({four:2,six:3}[s.harness]||0)+({boost:.5,triple:1.2}[s.auxGauges]||0);
 const seatDrop=s.frontSeats==='bucket'?.025:s.frontSeats==='sport'?.010:0,seatDelta=({sport:-8,bucket:-18}[s.frontSeats]||0),cageDelta=({half:28,full:42}[s.rollCage]||0)-(s.rollCage!=='stock'&&s.chassis==='reinforced'?12:0);
 return {mass,momentY:(mass-cageDelta)*.65+cageDelta*.82-(44+seatDelta)*seatDrop,cage,seatDrop,wheelRadius:s.steeringWheel==='sport'?.15:s.steeringWheel==='dish'?.155:null,wheelDish:s.steeringWheel==='dish'?.025:0,shiftLength:s.shiftKnob==='tall'?.125:.075,handbrakeLength:s.handbrakeLever==='hydraulic'?.19:s.handbrakeLever==='extended'?.14:.10,handbrakeFactor:s.handbrakeLever==='hydraulic'?1.35:s.handbrakeLever==='extended'?1.12:1,hydraulicHandbrake:s.handbrakeLever==='hydraulic',roofSupport:cage==='full'?1.45:cage==='half'?1.22:1,restraint:(s.frontSeats==='bucket'?.72:s.frontSeats==='sport'?.85:1)*(s.harness==='six'?.55:s.harness==='four'?.70:1),ambient:({warm:0xffc286,teal:0x66ddcd,violet:0xbb91ff}[s.ambientLighting]||0)};
}
